pub fn ranges(xs: List[Int]) -> Str {
  let sorted = xs.unique().sort()
  var parts: List[Str] = []
  var i = 0
  while i < sorted.len() {
    let first = sorted.get_or(i, 0)
    var j = i
    while j + 1 < sorted.len() and sorted.get_or(j + 1, 0) == sorted.get_or(j, 0) + 1 {
      j = j + 1
    }
    let last = sorted.get_or(j, 0)
    if j - i >= 2 {
      parts = parts.push(first.to_str() + "-" + last.to_str())
    } else if j - i == 1 {
      parts = parts.push(first.to_str())
      parts = parts.push(last.to_str())
    } else {
      parts = parts.push(first.to_str())
    }
    i = j + 1
  }
  return parts.join(",")
}
